description:
Implement a hook that attaches a ref to a DOM element and reads its `offsetWidth` and `offsetHeight` after it mounts. Returns `{ ref, width, height }` where `width` and `height` start at `0`.

**Example:**
```tsx
function Box() {
  const { ref, width, height } = useRefMeasure();
  return <div ref={ref}>{width}x{height}</div>;
}
```

starter_code:
import { useRef, useState, useEffect } from 'react';

export function useRefMeasure() {
  // your code here
}

test_suite:
test('returns width and height starting at 0', () => {
  const { result } = renderHook(() => useRefMeasure());
  expect(result.current.width).toBe(0);
  expect(result.current.height).toBe(0);
});

test('returns a ref object', () => {
  const { result } = renderHook(() => useRefMeasure());
  expect(result.current.ref).toBeDefined();
  expect(typeof result.current.ref).toBe('object');
});

test('updates dimensions when ref is attached to element', () => {
  const el = document.createElement('div');
  Object.defineProperty(el, 'offsetWidth', { value: 200, configurable: true });
  Object.defineProperty(el, 'offsetHeight', { value: 100, configurable: true });
  const { result } = renderHook(() => useRefMeasure());
  act(() => {
    result.current.ref.current = el;
  });
  expect(result.current.width).toBe(0);
  expect(result.current.height).toBe(0);
});

test('width and height are numbers', () => {
  const { result } = renderHook(() => useRefMeasure());
  expect(typeof result.current.width).toBe('number');
  expect(typeof result.current.height).toBe('number');
});

// __hidden__
test('ref.current is initially null', () => {
  const { result } = renderHook(() => useRefMeasure());
  expect(result.current.ref.current).toBeNull();
});

solution:
import { useRef, useState, useEffect } from 'react';

export function useRefMeasure() {
  const ref = useRef<HTMLElement>(null);
  const [size, setSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    if (ref.current) {
      setSize({
        width: ref.current.offsetWidth,
        height: ref.current.offsetHeight,
      });
    }
  }, []);

  return { ref, width: size.width, height: size.height };
}
